let closed = [], refused = [], skipped = [];
for (let issue of tool("list_issues", {})) {
  let approve = tool("ask_human", { id: issue.id, question: `Should we close issue ${issue.id}?` });
  if (approve) {
    try {
      tool("close_issue", { id: issue.id });
      closed.push(issue.id);
    } catch (error) {
      refused.push({ id: issue.id, reason: error });
    }
  } else {
    skipped.push(issue.id);
  }
}
{ closed, refused, skipped }

